// Validation et préparation des données
// Supports:
// - Single text: { text: '...' }
// - Batch commentaries: { job_type: 'batch_commentaries', segments: [{commentary_id, text}] }
const input = $input.first().json;
const body = input.body || input;

// Detect batch mode - supports segments array OR batch job types
const jobType = body.job_type || 'unit_translation';
const batchJobTypes = ['batch_commentaries', 'torah_commentary'];
const hasSegmentsArray = Array.isArray(body.segments) && body.segments.length > 0;
const isBatch = hasSegmentsArray;

// Extraction des paramètres
let text = body.text || '';
let segments = [];

if (hasSegmentsArray) {
  segments = body.segments;
  // Segments can be strings or objects with text property
  const firstSeg = segments[0];
  text = typeof firstSeg === 'string' ? firstSeg : (firstSeg.text || '');
}

const apiKey = body.api_key || '';
const openaiApiKey = body.openai_api_key || '';
const targetLanguage = body.target_language || 'fr';
const sourceLanguage = body.source_language || 'he';
const context = body.context || {};
const mode = body.mode || 'standard';
const commentator = body.commentator || context.commentator || '';

// Validation
const errors = [];
if (hasSegmentsArray) {
  segments.forEach((seg, i) => {
    const segText = typeof seg === 'string' ? seg : seg.text;
    if (!segText || segText.trim().length === 0) {
      errors.push(`Segment ${i}: le champ "text" est requis`);
    }
  });
} else {
  if (!text || text.trim().length === 0) {
    errors.push('Le champ "text" ou "segments" est requis');
  }
}
if (!apiKey) {
  errors.push('Le champ "api_key" est requis');
}
if (!openaiApiKey) {
  errors.push('Le champ "openai_api_key" est requis');
}

// Cache search params (only for single text, not batch)
let cacheSearchParams = `target_language=${targetLanguage}`;
const canSearchCache = !isBatch && !!(context.traite && context.page);
if (canSearchCache) {
  cacheSearchParams += `&traite=${encodeURIComponent(context.traite)}&page=${encodeURIComponent(context.page)}`;
  if (context.commentator) {
    cacheSearchParams += `&commentator=${encodeURIComponent(context.commentator)}`;
  }
  cacheSearchParams += `&text=${encodeURIComponent(text)}&exact=true`;
}

return [{
  json: {
    valid: errors.length === 0,
    errors: errors,
    project_id: body.project_id || context.project_id,
    isBatch: isBatch,
    jobType: jobType,
    text: text,
    segments: segments,
    traite: body.traite || context.traite,
    page: body.page || context.page,
    commentator: commentator,
    apiKey: apiKey,
    openaiApiKey: openaiApiKey,
    sourceLanguage: sourceLanguage,
    targetLanguage: targetLanguage,
    context: context,
    mode: mode,
    metadata: body.metadata || {},
    requestId: body.request_id || 'req_' + Date.now(),
    cacheSearchParams: cacheSearchParams,
    canSearchCache: canSearchCache
  }
}];

// Check cache result
const input = $input.first().json;
const prevData = $('Validate Input').first().json;

const data = input.body || input;
const statusCode = input.statusCode || 200;

const cacheHit = statusCode === 200 && data.found === true && data.translations?.length > 0;

if (cacheHit) {
  const cached = data.translations[0];
  return [{
    json: {
      cacheHit: true,
      cachedTranslation: cached.translated_text,
      cachedQuality: cached.quality_score || 0.9,
      originalText: prevData.text,
      targetLanguage: prevData.targetLanguage,
      context: prevData.context
    }
  }];
}

return [{
  json: {
    cacheHit: false,
    ...prevData
  }
}];

// Format cache hit response
const input = $input.first().json;

return [{
  json: {
    success: true,
    cached: true,
    translation: {
      original: input.originalText,
      final: input.cachedTranslation,
      source_language: 'he',
      target_language: input.targetLanguage
    },
    verification: {
      approved: true,
      confidence: input.cachedQuality
    },
    tokens: null
  }
}];

