// Extract job_id and prepare worker call
// Supports both single text and batch commentaries
const input = $input.first().json;
const prevData = $('Validate Input').first().json;

const data = input.body || input;
const statusCode = input.statusCode || 200;

if (statusCode >= 400 || !data.job_id) {
  return [{
    json: {
      success: false,
      error: {
        code: statusCode,
        message: data.error?.message || 'Erreur création job',
        status: 'JOB_CREATE_ERROR'
      }
    }
  }];
}

// Prepare segments for worker
let segments;
if (prevData.isBatch) {
  // Batch mode: segments already contain {commentary_id, text}
  segments = prevData.segments;
} else {
  // Single mode: wrap text in array
  segments = [prevData.text];
}

return [{
  json: {
    jobId: data.job_id,
    workerPayload: {
      job_id: data.job_id,
      job_type: prevData.jobType,
      text: prevData.text,
      segments: segments,
      traite: prevData.traite || prevData.context.traite,
      page: prevData.page || prevData.context.page,
      commentator: prevData.commentator,
      source_language: prevData.sourceLanguage,
      target_language: prevData.targetLanguage,
      mode: prevData.mode,
      api_key: prevData.apiKey,
      openai_api_key: prevData.openaiApiKey,
      context: prevData.context,
      metadata: prevData.metadata,
      request_id: prevData.requestId
    }
  }
}];

// Prepare response and worker call
const input = $input.first().json;

return [{
  json: {
    jobId: input.jobId,
    workerPayload: input.workerPayload,
    response: {
      success: true,
      cached: false,
      job_id: input.jobId
